def area(kind, a, b=None):
    if kind == 'circle':
        return math.pi * a * a
    elif kind == 'rect':
        return a * b
    elif kind == 'tri':
        return 0.5 * a * b

def perimeter(kind, a, b=None, c=None):
    if kind == 'circle':
        return 2 * math.pi * a
    elif kind == 'rect':
        return 2 * (a + b)
    elif kind == 'tri':
        return a + b + c
